// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        // Call setOwner with the fuzzed address
        c.setOwner(_owner);
        // General rule: owner state variable should equal the fuzzed address
        assertTrue(c.owner() == _owner);
    }
}

